<?php
declare(strict_types=1); require dirname(__DIR__,3).'/bootstrap.php'; public_emergency_auth(); $body=public_json_body();
$installationId=trim((string)($body['installation_id']??''));$action=(string)($body['action']??'');$reason=trim((string)($body['reason']??''));$actor=trim((string)($body['actor']??'emergency-console'));
if($installationId===''||$reason===''||!in_array($action,['disable_remote','enable_remote','disable_order_intake','enable_order_intake'],true))public_json(['ok'=>false,'error'=>'invalid_control'],400);
$pdo=public_db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT active,remote_enabled,order_intake_enabled FROM installations WHERE installation_id=? FOR UPDATE');$q->execute([$installationId]);$before=$q->fetch();if(!$before){$pdo->rollBack();public_json(['ok'=>false,'error'=>'not_found'],404);} $after=$before; if($action==='disable_remote')$after['remote_enabled']=0;if($action==='enable_remote')$after['remote_enabled']=1;if($action==='disable_order_intake')$after['order_intake_enabled']=0;if($action==='enable_order_intake')$after['order_intake_enabled']=1;$u=$pdo->prepare('UPDATE installations SET remote_enabled=?,order_intake_enabled=? WHERE installation_id=?');$u->execute([(int)$after['remote_enabled'],(int)$after['order_intake_enabled'],$installationId]);$a=$pdo->prepare('INSERT INTO emergency_audit(installation_id,actor,action_key,reason,before_json,after_json) VALUES(?,?,?,?,?,?)');$a->execute([$installationId,$actor,$action,$reason,json_encode($before),json_encode($after)]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}public_json(['ok'=>true,'installation_id'=>$installationId,'remote_enabled'=>(bool)$after['remote_enabled'],'order_intake_enabled'=>(bool)$after['order_intake_enabled']]);
